// Chewing-gum input rows: sink gently while typing, stay sunk while filled,
// bounce back and fling the old value into darkness when erased.
function GumRow({ value, children }: { value: string; children: ReactNode }) {
  const [ghost, setGhost] = useState<string | null>(null);
  const [ghostId, setGhostId] = useState(0);
  const [bouncing, setBouncing] = useState(false);
  const prevRef = useRef(value);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  useEffect(() => {
    const was = prevRef.current;
    prevRef.current = value;
    timers.current.forEach(clearTimeout);
    timers.current = [];
    if (was && !value) {
      setGhost(was);
      setGhostId((n) => n + 1);
      setBouncing(true);
      timers.current = [
        setTimeout(() => setGhost(null), 800),
        setTimeout(() => setBouncing(false), 700),
      ];
    } else {
      setGhost(null);
      setBouncing(false);
    }
    return () => { timers.current.forEach(clearTimeout); };
  }, [value]);
  return (
    <div className={"gum-row relative" + (value ? " gum-sunk" : "") + (bouncing ? " gum-bounce" : "")}>
      {children}
      {ghost ? <span key={ghostId} className="gum-ghost">{ghost}</span> : null}
    </div>
  );
}

// Apple-style animated count-up for hero numbers.
const AnimatedNumber = ({ value, format }: { value: number; format: (n: number) => string }): ReactElement => {
  const [display, setDisplay] = useState(value);
  const prev = useRef(value);
  useEffect(() => {
    const from = prev.current;
    if (from === value) {
      setDisplay(value);
      return;
    }
    let raf = 0;
    const t0 = performance.now();
    const tick = (t: number) => {
      const p = Math.min(1, (t - t0) / 650);
      const eased = 1 - Math.pow(1 - p, 3);
      setDisplay(from + (value - from) * eased);
      if (p < 1) raf = requestAnimationFrame(tick);
      else prev.current = value;
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [value]);
  return <>{format(display)}</>;
};

