// Smart icon for a custom app name: matches the word, else a stable fitting pick.
const guessIconFor = (label: string): string => {
  const t = label.toLowerCase();
  if (/scooter|vespa|moped/.test(t)) return "scooter";
  if (/bike|bicycle|ebike|e-bike|cycling/.test(t)) return "bicycle";
  if (/motorcycle|harley|moto/.test(t)) return "motorcycle";
  if (/truck|freight|haul|logistic|schneider|swift/.test(t)) return "pickup";
  if (/van|cargo/.test(t)) return "van";
  if (/suv/.test(t)) return "suv";
  if (/boat|ship|ferry|yacht|pontoon|jetski|jet ski|captain|marina/.test(t)) return "boat";
  if (/plane|flight|charter|air|pilot/.test(t)) return "plane";
  if (/car|auto|ride|uber|lyft|taxi|sedan/.test(t)) return "sedan";
  if (/package|parcel|amazon|flex|deliver/.test(t)) return "package";
  if (/grocer|instacart|shop|food|eat/.test(t)) return "bag";
  const pool = ["sedan", "suv", "pickup", "van", "motorcycle", "scooter", "bicycle", "package"];
  let h = 0;
  for (let i = 0; i < t.length; i++) h = (h * 31 + t.charCodeAt(i)) >>> 0;
  return pool[h % pool.length];
};

