function formatCurrency(n: number): string {
  return n.toLocaleString("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

function formatNumber(n: number, digits = 1): string {
  return n.toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

function formatShortDate(iso: string): string {
  return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

/** Net-profit math for one offer (used by the Compare tab). */
function calcOfferNet(payout: number, miles: number, gas: number, mpg: number, retMiles = 0, wearRate = WEAR_COST_PER_MILE, speedMph = AVG_SPEED_MPH) {
  const totalMi = miles + retMiles;
  const fuel = totalMi > 0 && mpg > 0 ? (totalMi / mpg) * gas : 0;
  const wear = totalMi * wearRate;
  const total = fuel + wear;
  const net = payout - total;
  const hours = speedMph > 0 ? totalMi / speedMph : 0;
  return { fuel, wear, total, net, hours, hourly: hours > 0 ? net / hours : 0, totalMi };
}

/** Monday (local) of the week containing d, as YYYY-MM-DD. */
function weekKey(d: Date): string {
  const x = new Date(d);
  const day = (x.getDay() + 6) % 7;
  x.setDate(x.getDate() - day);
  x.setHours(0, 0, 0, 0);
  return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, "0")}-${String(x.getDate()).padStart(2, "0")}`;
}

function readLocal(key: string, fallback: string): string {
  try {
    return localStorage.getItem(key) ?? fallback;
  } catch {
    return fallback;
  }
}

function writeLocal(key: string, value: string) {
  try {
    localStorage.setItem(key, value);
  } catch {
    // private mode etc — non-fatal
  }
}

/* ---------- RevenueCat in-app purchases (replaces Whop) ---------- */

// True only inside the real Android app (Capacitor webview), never in a browser.
const isNativeApp = () => {
  const cap = (window as any).Capacitor;
  return !!cap && typeof cap.isNativePlatform === "function" && cap.isNativePlatform();
};

let rcConfigured = false;
const ensureRC = async (userId: string): Promise<boolean> => {
  if (!isNativeApp()) return false;
  try {
    if (!rcConfigured) {
      await Purchases.configure({ apiKey: REVENUECAT_API_KEY });
      rcConfigured = true;
    }
    try {
      await Purchases.logIn({ appUserID: userId });
    } catch {
      /* already logged in as this user */
    }
    return true;
  } catch {
    return false;
  }
};

const rcHasPremium = async (userId: string): Promise<boolean> => {
  try {
    if (!(await ensureRC(userId))) return false;
    const { customerInfo } = await Purchases.getCustomerInfo();
    return !!customerInfo?.entitlements?.active?.[PREMIUM_ENTITLEMENT];
  } catch {
    return false;
  }
};

// If the Play Store entitlement is active, mirror it into profiles.is_premium.
const rcSyncPremiumToProfile = async (userId: string): Promise<boolean> => {
  if (!supabase) return false;
  try {
    const has = await rcHasPremium(userId);
    if (has) {
      await supabase.from("profiles").upsert({ id: userId, is_premium: true }, { onConflict: "id" });
    }
    return has;
  } catch {
    return false;
  }
};

function usePremiumPurchase(onUnlocked: () => void) {
  const [pkg, setPkg] = useState<any>(null);
  const [price, setPrice] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  useEffect(() => {
    (async () => {
      try {
        if (!supabase || !isNativeApp()) return;
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;
        if (!(await ensureRC(user.id))) return;
        const offerings = await Purchases.getOfferings();
        const first = offerings?.current?.availablePackages?.[0];
        if (first) {
          setPkg(first);
          setPrice(first?.product?.priceString || "");
        }
      } catch {
        /* store products not configured yet — Whop fallback renders below */
      }
    })();
  }, []);

  const buy = async () => {
    if (!supabase || !pkg) return;
    setBusy(true);
    setErr("");
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("signin");
      const { customerInfo } = await Purchases.purchasePackage({ aPackage: pkg });
      if (customerInfo?.entitlements?.active?.[PREMIUM_ENTITLEMENT]) {
        await rcSyncPremiumToProfile(user.id);
        onUnlocked();
      } else {
        setErr("Purchase went through but premium isn't active yet — tap Restore below.");
      }
    } catch (e: any) {
      const cancelled = e?.code === "1" || /cancel/i.test(String(e?.message || ""));
      if (!cancelled && String(e?.message || "") !== "signin") {
        setErr("Couldn't complete the purchase. Try again.");
      }
    }
    setBusy(false);
  };

  const restore = async () => {
    if (!supabase) return;
    setBusy(true);
    setErr("");
    try {
      const { data: { user } } = await supabase.auth.getUser();
      const { customerInfo } = await Purchases.restorePurchases();
      if (customerInfo?.entitlements?.active?.[PREMIUM_ENTITLEMENT]) {
        if (user) await rcSyncPremiumToProfile(user.id);
        onUnlocked();
      } else {
        setErr("No premium purchase found on this account.");
      }
    } catch {
      setErr("Couldn't check purchases. Try again.");
    }
    setBusy(false);
  };

  return { pkg, price, busy, err, buy, restore };
}

