function PremiumBuyButton({ onUnlocked }: { onUnlocked: () => void }) {
  const [showFeatures, setShowFeatures] = useState(false);
  const wrappedUnlocked = () => {
    setShowFeatures(false);
    onUnlocked();
  };
  const { pkg, price, busy, err, buy, restore } = usePremiumPurchase(wrappedUnlocked);

  const handleContinue = () => {
    if (!pkg) {
      // Play products aren't configured yet — Whop checkout stays working meanwhile.
      window.open(WHOP_URL, "_blank", "noopener,noreferrer");
      return;
    }
    buy();
  };

  return (
    <div>
      <button
        onClick={() => setShowFeatures(true)}
        disabled={busy}
        className="block w-full py-3 rounded-xl bg-gradient-to-r from-[#ffecd0] to-[#ffecd0] text-sm font-extrabold text-[#0f0f16] active:scale-[0.98] transition-transform disabled:opacity-60"
      >
        {busy ? "Processing…" : price ? `Upgrade to Premium — ${price}` : "Upgrade to Premium"}
      </button>
      {err ? <p className="text-[11px] text-red-400 mt-2 leading-relaxed">{err}</p> : null}
      <button
        onClick={restore}
        disabled={busy}
        className="mt-2.5 text-[11px] font-semibold text-zinc-500 underline underline-offset-2 disabled:opacity-60"
      >
        Already paid? Restore purchases
      </button>
      {showFeatures && (
        <PremiumFeaturesModal
          price={price}
          busy={busy}
          onClose={() => setShowFeatures(false)}
          onContinue={handleContinue}
        />
      )}
    </div>
  );
}

