  const [presetMemory, setPresetMemory] = useState<Record<string, { payout: string; mileage: string }>>({});
  const [returnTripEnabled, setReturnTripEnabled] = useState(false);
  const [returnMileage, setReturnMileage] = useState("");
  const [results, setResults] = useState<Results | null>(null);
  const [error, setError] = useState("");

  // v2 Phase 3: AI offer-photo scanner state
  const [scanBusy, setScanBusy] = useState(false);
  const [scanError, setScanError] = useState("");
  const [scanOk, setScanOk] = useState(false);
  const [watching, setWatching] = useState(false);
  const [watchMsg, setWatchMsg] = useState("");
  const [verdict, setVerdict] = useState<{ verdict: "TAKE" | "SKIP"; reasons: string[] } | null>(null);
  const [verdictBusy, setVerdictBusy] = useState(false);
  const [verdictError, setVerdictError] = useState("");
  // v2: weekly briefing, shift planner, what-if
  const [briefing, setBriefing] = useState<{ summary: string; tip: string } | null>(null);
  const [briefingBusy, setBriefingBusy] = useState(false);
  const [briefingError, setBriefingError] = useState("");
  const [planner, setPlanner] = useState<{ best: string[]; avoid: string } | null>(null);
  const [plannerBusy, setPlannerBusy] = useState(false);
  const [plannerError, setPlannerError] = useState("");
  const [whatIfThreshold, setWhatIfThreshold] = useState("");
  // v2: per-app history — which gig app each saved route belongs to
  const [historyPlatformFilter, setHistoryPlatformFilter] = useState<string>("all");

  const OFFER_SCAN_PROMPT =
    'You are reading a gig-work offer screenshot (DoorDash, Uber Eats, trucking or charter offers, etc.). Extract the payout (dollar amount offered) and the trip distance in miles. Reply ONLY valid JSON like {"payout": 8.5, "miles": 10}. Numbers only, no $ signs or text. If a value is unclear, use 0.';
  const [history, setHistory] = useState<RouteHistoryRow[]>([]);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [clearStep, setClearStep] = useState<"idle" | "confirm">("idle");
  // Last cleared batch — kept so it can be recovered (survives app restarts)
  const [clearedBackup, setClearedBackup] = useState<RouteHistoryRow[] | null>(() => {
    try {
      const raw = localStorage.getItem("routemax_cleared_history_backup");
      const parsed = raw ? JSON.parse(raw) : null;
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
    } catch {
      // ignore
    }
    return null;
  });
  const [acceptedClearStep, setAcceptedClearStep] = useState<"idle" | "confirm">("idle");
  const [acceptedBackup, setAcceptedBackup] = useState<string[] | null>(() => {
    try {
      const raw = localStorage.getItem("routemax_accepted_backup");
      const parsed = raw ? JSON.parse(raw) : null;
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
    } catch {
      // ignore
    }
    return null;
  });
  const [expandedMonth, setExpandedMonth] = useState<string | null>(null);
  const [expandedQuarter, setExpandedQuarter] = useState<string | null>(null);
  const [expandedRouteId, setExpandedRouteId] = useState<string | null>(null);
  const [expandedAcceptedBox, setExpandedAcceptedBox] = useState<string | null>(null);
  const [expandedStat, setExpandedStat] = useState<string | null>(null);
  const [expandedTaxQ, setExpandedTaxQ] = useState<string | null>(null);
  // Armed by programmatic fills (scan, watcher, Eric, preset tap) — fires one
  // automatic calculation once payout+mileage land in state.
  const autoCalcRef = useRef<{ save: boolean } | null>(null);
  const [calcTick, setCalcTick] = useState(0);
  // User-added platforms (trucking companies, other gig apps…) — saved on this device
  const [customPlatforms, setCustomPlatforms] = useState<CustomPlatform[]>(() => {
    try {
      const raw = localStorage.getItem("routemax_custom_platforms");
      const parsed = raw ? JSON.parse(raw) : null;
      if (Array.isArray(parsed)) return parsed.filter((p) => p && p.key && p.label);
    } catch {
      // ignore
    }
    return [];
  });
  const [addingPlatform, setAddingPlatform] = useState(false);
  const [newPlatformName, setNewPlatformName] = useState("");
  const [newPlatformColor, setNewPlatformColor] = useState(0);
  const customPresets: Preset[] = customPlatforms.map((cp) => {
    const c = CUSTOM_COLORS[cp.colorIdx] || CUSTOM_COLORS[0];
    const iconKey = cp.icon || guessIconFor(cp.label);
    return { key: cp.key, label: cp.label, icon: VEHICLE_ICONS[iconKey] || Truck, payout: "", mileage: "", gasPrice: "", mpg: "", wear: "", accent: c.accent, bg: c.bg };
  });
  const allPresets: Preset[] = [...PRESETS, ...customPresets];

  // Your vehicle — picked from real brands/models. Drives MPG, wear, speed accuracy.
  type VehiclePick = { brand: string; model: string; type: string; speed: number; color: string; fuel: string };
  const [vehicleOpen, setVehicleOpen] = useState(false);
  // Free route lookup: OpenStreetMap Nominatim (geocode) + OSRM (route). No API key.
  const [routeOpen, setRouteOpen] = useState(false);
  const [routeFrom, setRouteFrom] = useState("");
  const [routeTo, setRouteTo] = useState("");
  const [routeLoading, setRouteLoading] = useState(false);
  const [routeError, setRouteError] = useState("");
  const [routeInfo, setRouteInfo] = useState<string | null>(null);
  type GeoSugg = { name: string; lat: string; lon: string };
  const [fromSugg, setFromSugg] = useState<GeoSugg[]>([]);
  const [toSugg, setToSugg] = useState<GeoSugg[]>([]);
  const [fromCoord, setFromCoord] = useState<GeoSugg | null>(null);
  const [toCoord, setToCoord] = useState<GeoSugg | null>(null);
  const [suggLoading, setSuggLoading] = useState<"from" | "to" | null>(null);
  const [locLoading, setLocLoading] = useState<"from" | "to" | null>(null);
  const useCurrentLocation = (which: "from" | "to") => {
    if (!navigator.geolocation) { setRouteError("Location isn't available on this device."); return; }
    setLocLoading(which); setRouteError("");
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        try {
          const { latitude, longitude } = pos.coords;
          const r = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const j = await r.json();
          const g: GeoSugg = {
            name: j.display_name || "Current location",
            lat: String(latitude), lon: String(longitude),
          };
          pickSugg(which, g);
        } catch { setRouteError("Couldn't read your location — try typing it."); }
        finally { setLocLoading(null); }
      },
      () => { setLocLoading(null); setRouteError("Location permission denied — type the address instead."); },
      { enableHighAccuracy: false, timeout: 12000, maximumAge: 60000 }
    );
  };
  // Debounced address autocomplete (free OpenStreetMap) for the route fields.
  useEffect(() => {
    if (!routeOpen) return;
    const run = (q: string, which: "from" | "to") => {
      if (q.trim().length < 3) { (which === "from" ? setFromSugg : setToSugg)([]); return; }
      const t = setTimeout(async () => {
        setSuggLoading(which);
        try {
          const r = await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=5&addressdetails=0&q=${encodeURIComponent(q.trim())}`);
          const j = await r.json();
          const list: GeoSugg[] = (Array.isArray(j) ? j : []).slice(0, 5).map((p: any) => ({ name: p.display_name, lat: p.lat, lon: p.lon }));
          (which === "from" ? setFromSugg : setToSugg)(list);
        } catch { (which === "from" ? setFromSugg : setToSugg)([]); }
        finally { setSuggLoading(null); }
      }, 500);
      return () => clearTimeout(t);
    };
    const c1 = run(routeFrom, "from");
    const c2 = run(routeTo, "to");
    return () => { c1 && c1(); c2 && c2(); };
  }, [routeFrom, routeTo, routeOpen]);
  const pickSugg = (which: "from" | "to", g: GeoSugg) => {
    if (which === "from") { setRouteFrom(g.name.split(",").slice(0, 3).join(",")); setFromCoord(g); setFromSugg([]); }
    else { setRouteTo(g.name.split(",").slice(0, 3).join(",")); setToCoord(g); setToSugg([]); }
  };
  // Real speed from the route lookup — overrides the generic vehicle speed in profit math.
  const [tripSpeed, setTripSpeed] = useState<number | null>(null);
  const [tripCityMi, setTripCityMi] = useState<number | null>(null);
  const [tripHwyMi, setTripHwyMi] = useState<number | null>(null);
  const [tripSecs, setTripSecs] = useState<number | null>(null);
  const [tripModes, setTripModes] = useState<{ drive: number | null; bike: number | null; walk: number | null } | null>(null);
  const [tripWeather, setTripWeather] = useState<string | null>(null);
